Output4Time Complexity: O(n * m). Here n is the number of ranges and m is the maximum number of elements in any of the ranges.Auxiliary Space: O(m), due to hash map.[Efficient Approach] Using Difference ArrayThe idea is to use a difference array technique to efficiently handle range updates. Instead of individually incrementing each number in a range, we mark the start and end of ranges. For each range [l[i], r[i]], we increment the value at index l[i] and decrement the value at index r[i]+1. By calculating the prefix sum, we can determine the frequency of each number across all ranges.Step by step approach:Find the maximum value (maxi) in all ranges.Create a difference array of size maxi+2.For each range, increment diff[l[i]] and decrement diff[r[i]+1].Calculate prefix sum while tracking maximum frequency.Return the index with maximum frequency.
            C++

    #include <iostream>
#include <vector>
#include <climits>
using namespace std;

int maxOccured(vector<int> &l, vector<int> &r) {
    int n = l.size();

    // Find maximum value in ranges
    int maxi = INT_MIN;
    for (int i=0; i<n; i++) maxi = max(maxi, r[i]);

    vector<int> diff(maxi + 2, 0);

    // Mark the starting and ending of ranges
    for (int i = 0; i < n; i++) {

        // Increment at start of range
        diff[l[i]]++;   

        // Decrement at end+1 of range
        diff[r[i] + 1]--;   
    }

    // Calculate the prefix sum and find maximum frequency
    int maxFreq = diff[0];
    int result = 0;

    for (int i = 1; i <= maxi; i++) {

        // Calculate prefix sum
        diff[i] += diff[i - 1];

        // Update result if current frequency is higher
        if (diff[i] > maxFreq) {
            maxFreq = diff[i];
            result = i;
        }
    }

    return result;
}

int main() {
    vector<int> l = {1, 2, 4, 3};
    vector<int> r = {6, 4, 8, 5};
    cout << maxOccured(l, r);
    return 0;
}


